package lobby

import "encoding/binary"

// TankmanGroup is one name pool from a nation's tankmen XML: the ids the
// client's `tankmen_cfg` accepts for a first name, a last name and an icon.
// Generated by wotgarage into garage_gen.go.
type TankmanGroup struct {
	Nation    uint8
	IsPremium bool
	IsFemale  bool
	FirstIDs  []uint16
	LastIDs   []uint16
	IconIDs   []uint16
}

// TankmanRoles is the role order the barracks is filled in. The names are
// `skills_constants.ROLE_NAMES`; the compact descriptor stores their
// `SKILL_INDICES` value, which is why tankmanRoleIndex exists.
var TankmanRoles = []string{"commander", "gunner", "driver", "radioman", "loader"}

// tankmanRoleIndex is `skills_constants.SKILL_INDICES` for the five roles.
// The descriptor packs `(index << 1) | (skillsEfficiencyXP >> 16 & 1)` into
// one byte, and `TankmanDescr` reads the role back as
// `SKILL_NAMES[roleID >> 1]`.
var tankmanRoleIndex = map[string]byte{
	"commander": 1,
	"radioman":  2,
	"driver":    3,
	"gunner":    4,
	"loader":    5,
}

// tankmanSkillsEfficiencyXP is `MAX_SKILLS_EFFICIENCY_XP`: a fully efficient
// crew member. It is 0x0186A0, so the low bit of the role byte is 1.
const tankmanSkillsEfficiencyXP = 100000

// TankmanCompDescr builds one tankman's compact descriptor, byte for byte as
// `tankmen.generateCompactDescr` writes it for a crew member with no skills:
//
//	[header = tankman(8) | nation << 4]
//	[flags]                       TankmanFlags.pack()
//	[vehicleTypeID]               1 byte, or 2 big-endian when > 255
//	[roleID][xp hi][xp lo]        roleID = (SKILL_INDICES[role] << 1) | (xp>>16 & 1)
//	[numSkills = 0][lastSkillLevel = 0]
//	[firstNameID >H][lastNameID >H][iconID >H][freeXP >I]
//	[dossierCompactDescr]         empty
//
// `TankmanDescr.__initFromCompactDescr` validates every id against the
// nation config and the vehicle type against the nation's vehicle list, so
// the caller must pass ids from AllTankmanGroups and a real typeID.
func TankmanCompDescr(nation uint8, isPremium, isFemale bool, firstNameID, lastNameID, iconID, vehicleTypeID uint16, role string) []byte {
	roleIdx, ok := tankmanRoleIndex[role]
	if !ok {
		return nil
	}
	extended := vehicleTypeID > 255
	var flags byte
	if extended {
		flags |= 128 // EXTENDED_VEHICLE_TYPE_ID_FLAG
	}
	if isPremium {
		flags |= 64 // IS_PREMIUM_FLAG
	}
	if isFemale {
		flags |= 32 // IS_FEMALE_FLAG
	}
	cd := make([]byte, 0, 20)
	cd = append(cd, itemTankman|nation<<4)
	cd = append(cd, flags)
	if extended {
		cd = binary.BigEndian.AppendUint16(cd, vehicleTypeID)
	} else {
		cd = append(cd, byte(vehicleTypeID))
	}
	sef := tankmanSkillsEfficiencyXP
	cd = append(cd, roleIdx<<1|byte(sef>>16&1), byte(sef>>8&0xff), byte(sef&0xff))
	cd = append(cd, 0, 0) // numSkills, lastSkillLevel
	cd = binary.BigEndian.AppendUint16(cd, firstNameID)
	cd = binary.BigEndian.AppendUint16(cd, lastNameID)
	cd = binary.BigEndian.AppendUint16(cd, iconID)
	cd = binary.BigEndian.AppendUint32(cd, 0) // freeXP
	return cd
}

// tankmanGroupsPerNation caps how many name pools one nation contributes.
// The client declares ~350 pools per nation (one per vehicle, for the
// per-vehicle crew names), which would put ~19k tankmen in the barracks —
// far more than the UI can present and a needless 400 KB in the sync stream.
// The cap keeps the normal pools (a handful) and then takes premium pools in
// declaration order, so every nation still gets normal, premium and female
// crew for every role.
const tankmanGroupsPerNation = 24

// TankmanInventory is the barracks: `{invID: compDescr}` for one tankman per
// (name pool, role). `vehicleTypeID` supplies the nation's vehicle type the
// tankman is nominally trained for — the descriptor requires a real one.
//
// The instance ids start at 1 and are dense; the client keys the barracks by
// them and never renumbers.
func TankmanInventory(vehicleTypeID func(nation uint8) (uint16, bool)) map[int64]any {
	out := map[int64]any{}
	perNation := map[uint8]int{}
	var invID int64 = 1
	for _, g := range AllTankmanGroups {
		if perNation[g.Nation] >= tankmanGroupsPerNation {
			continue
		}
		typeID, ok := vehicleTypeID(g.Nation)
		if !ok {
			continue
		}
		perNation[g.Nation]++
		for _, role := range TankmanRoles {
			cd := TankmanCompDescr(g.Nation, g.IsPremium, g.IsFemale,
				g.FirstIDs[0], g.LastIDs[0], g.IconIDs[0], typeID, role)
			if cd == nil {
				continue
			}
			out[invID] = cd
			invID++
		}
	}
	return out
}
